  ('cekirdek.kalem','bukum_adet','Büküm adedi','Ölçü ve geometri',92,'tamsayi','ozellik',true,NULL,0,NULL),
  ('cekirdek.kalem','acili_kesim','Açılı kesim','Ölçü ve geometri',93,'evet_hayir','ozellik',true,NULL,NULL,NULL);

